:root { --space-1: 8px; --space-2: 16px; --space-3: 24px; --space-4: 32px; --space-5: 48px; --radius: 12px; --radius-sm: 8px; --font-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; --admin-bg: #060b14; --admin-surface: #0f1a2b; --admin-border: #1d3050; --admin-accent: #22d3ee; --admin-accent-dim: #0e7490; --admin-text: #e2e8f0; --admin-muted: #7d93b4; --doctor-bg: #f4f8ff; --doctor-surface: #ffffff; --doctor-border: #dbe4f5; --doctor-accent: #2563eb; --doctor-accent-dim: #1d4ed8; --doctor-text: #0f172a; --doctor-muted: #64748b; --ok: #16a34a; --warn: #d97706; --err: #dc2626; }* { box-sizing: border-box; margin: 0px; padding: 0px; }html, body { height: 100%; }body { font-family: var(--font-base); font-size: 16px; line-height: 1.5; -webkit-font-smoothing: antialiased; }.landing-body { min-height: 100vh; display: grid; place-items: center; background: radial-gradient(circle at 50% 0%, rgb(15, 26, 43) 0%, rgb(6, 11, 20) 70%); color: var(--admin-text); padding: var(--space-3); }.landing-card { text-align: center; background: var(--admin-surface); border: 1px solid var(--admin-border); border-radius: var(--radius); padding: var(--space-5) var(--space-4); max-width: 520px; width: 100%; box-shadow: rgba(0, 0, 0, 0.45) 0px 20px 60px; }.landing-card h1 { font-size: 28px; letter-spacing: 0.5px; }.landing-card .subtitle { color: var(--admin-muted); margin-top: var(--space-1); }.landing-card .phase-tag { display: inline-block; margin-top: var(--space-2); padding: 4px 12px; border: 1px solid var(--admin-accent-dim); border-radius: 999px; color: var(--admin-accent); font-size: 13px; }.shield-badge { font-size: 48px; margin-bottom: var(--space-2); color: var(--admin-accent); text-shadow: rgba(34, 211, 238, 0.5) 0px 0px 24px; }.landing-actions { margin-top: var(--space-4); display: flex; gap: var(--space-2); flex-wrap: wrap; justify-content: center; }.auth-card { max-width: 420px; width: 100%; margin: var(--space-5) auto; padding: var(--space-4); border-radius: var(--radius); box-shadow: rgba(0, 0, 0, 0.25) 0px 20px 60px; }.auth-card h1 { font-size: 26px; }.auth-subtitle { margin-top: var(--space-1); font-size: 14px; }.field { display: block; margin-top: var(--space-2); }.field-label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; }.field input { width: 100%; padding: 12px 14px; border-radius: var(--radius-sm); border: 1px solid transparent; font-size: 15px; transition: border-color 0.15s, box-shadow 0.15s; }.field input:focus { outline: none; }.error-message { margin-top: var(--space-2); padding: 10px 12px; border-radius: var(--radius-sm); font-size: 14px; }.btn { display: inline-block; padding: 12px 18px; border-radius: var(--radius-sm); border: 1px solid transparent; font-size: 15px; font-weight: 600; text-decoration: none; cursor: pointer; transition: transform 0.08s, background 0.15s, box-shadow 0.15s; }.btn:active { transform: translateY(1px); }.btn-block { width: 100%; margin-top: var(--space-3); }.btn-sm { padding: 8px 14px; font-size: 14px; }.btn-admin { background: linear-gradient(135deg, var(--admin-accent-dim), var(--admin-accent)); color: rgb(6, 11, 20); }.btn-admin:hover { box-shadow: rgba(34, 211, 238, 0.45) 0px 0px 18px; }.btn-doctor { background: linear-gradient(135deg, var(--doctor-accent), var(--doctor-accent-dim)); color: rgb(255, 255, 255); }.btn-doctor:hover { box-shadow: rgba(37, 99, 235, 0.35) 0px 6px 18px; }.btn-outline { background: transparent; border-color: currentcolor; color: inherit; }.btn-outline:hover { background: rgba(255, 255, 255, 0.08); }.topbar { display: flex; align-items: center; justify-content: space-between; padding: var(--space-2) var(--space-3); gap: var(--space-2); flex-wrap: wrap; }.topbar-left { display: flex; align-items: center; gap: var(--space-2); }.topbar-right { display: flex; align-items: center; gap: var(--space-2); }.topbar-title { font-size: 20px; }.topbar-sub { font-size: 13px; opacity: 0.8; }.shield-mini, .cross-mini { font-size: 28px; }.dashboard { max-width: 1080px; margin: 0px auto; padding: var(--space-3); }.status-pending { color: var(--warn); }.status-warn { color: var(--warn); }.status-ok { color: var(--ok); }.status-err { color: var(--err); }@media (max-width: 600px) {
  .topbar-title { font-size: 18px; }
