}.hospital-name { margin-top: 7px; color: rgb(255, 255, 255); font-size: 14px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }

:root { --green: #2457a6; --green-dark: #173f7a; --green-soft: #edf4ff; --border: #dce4ee; --text: #192235; --muted: #667085; --surface: #fff; --background: #f5f7fb; --danger: #c93838; }* { box-sizing: border-box; }body.doctor-body { margin: 0px; min-height: 100vh; background: var(--background); color: var(--text); font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }.hero-header { position: relative; min-height: 230px; background: url("http://localhost/assets/header-team.png") center center / cover no-repeat; border-bottom: 1px solid rgb(217, 226, 238); }.hero-overlay { position: absolute; inset: 0px; background: linear-gradient(90deg, rgba(255, 255, 255, 0.97) 0%, rgba(255, 255, 255, 0.88) 35%, rgba(255, 255, 255, 0.15) 70%, rgba(255, 255, 255, 0.08) 100%); }.hero-content { position: relative; z-index: 1; min-height: 230px; padding: 28px clamp(24px, 4vw, 58px); display: flex; align-items: center; justify-content: space-between; gap: 30px; }.brand-name { margin: 0px 0px 24px; font-size: 28px; font-weight: 800; letter-spacing: -0.02em; }.doctor-identity { display: flex; align-items: center; gap: 16px; }.avatar { width: 58px; height: 58px; border-radius: 50%; display: grid; place-items: center; background: var(--green); color: rgb(255, 255, 255); font-size: 20px; font-weight: 800; }.doctor-identity h1 { margin: 0px 0px 6px; font-size: 28px; }.doctor-identity p { margin: 3px 0px; color: rgb(57, 70, 90); font-size: 14px; }.hero-actions { display: flex; align-items: center; gap: 12px; align-self: flex-end; margin-bottom: 22px; }.date-card, .hero-button { border: 1px solid rgba(207, 216, 211, 0.95); background: rgba(255, 255, 255, 0.94); box-shadow: rgba(36, 87, 166, 0.1) 0px 8px 24px; border-radius: 9px; color: rgb(41, 52, 73); }.date-card { display: grid; gap: 7px; padding: 14px 18px; min-width: 205px; }.date-card span { font-size: 14px; }.hero-button { padding: 16px 18px; cursor: pointer; font-weight: 700; }.badge { display: inline-grid; place-items: center; min-width: 20px; height: 20px; border-radius: 10px; background: var(--green); color: rgb(255, 255, 255); margin-left: 4px; }.workspace { width: min(1540px, 100% - 34px); margin: 28px auto 50px; display: grid; grid-template-columns: 230px minmax(0px, 1fr); gap: 24px; }.sidebar { position: sticky; top: 20px; align-self: start; display: grid; padding: 12px; border: 1px solid var(--border); border-radius: 12px; background: rgb(255, 255, 255); box-shadow: rgba(36, 87, 166, 0.05) 0px 6px 24px; }.nav-link { padding: 12px 14px; border: 0px; border-radius: 8px; background: transparent; text-align: left; color: rgb(52, 64, 84); font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 650; cursor: pointer; }.nav-link:hover, .nav-link.active { background: var(--green-soft); color: var(--green-dark); }.content-area { min-width: 0px; }.page-heading { padding: 4px 4px 20px; }.page-heading h2 { margin: 4px 0px 8px; font-size: 32px; }.page-heading p { margin: 0px; color: var(--muted); }.eyebrow { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 800; font-size: 11px !important; color: var(--green) !important; }.panel { padding: 22px; border: 1px solid var(--border); border-radius: 12px; background: rgb(255, 255, 255); box-shadow: rgba(36, 87, 166, 0.05) 0px 6px 24px; }.panel-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-bottom: 18px; }.panel-heading h3 { margin: 2px 0px 5px; font-size: 24px; }.panel-heading p { margin: 0px; color: var(--muted); }.heading-actions { display: flex; gap: 9px; flex-wrap: wrap; }.primary-action, .secondary-action, .row-action, .upload-button { border-radius: 7px; font-weight: 750; cursor: pointer; }.primary-action { padding: 10px 15px; border: 1px solid var(--green); background: var(--green); color: rgb(255, 255, 255); }.primary-action:hover { background: var(--green-dark); }.secondary-action, .upload-button { padding: 10px 15px; border: 1px solid rgb(188, 201, 216); background: rgb(255, 255, 255); color: rgb(35, 74, 124); }.secondary-action:hover, .upload-button:hover, .row-action:hover { background: var(--green-soft); border-color: var(--green); }.table-wrap { overflow-x: auto; }table { width: 100%; border-collapse: collapse; min-width: 960px; font-size: 14px; }th, td { padding: 12px 13px; border: 1px solid var(--border); text-align: left; vertical-align: middle; }th { background: rgb(247, 249, 252); color: rgb(35, 74, 124); font-weight: 800; }tbody tr:hover { background: rgb(251, 252, 255); }.status { display: inline-block; padding: 4px 8px; border-radius: 5px; font-size: 12px; font-weight: 800; background: rgb(242, 244, 247); }.status-ready, .status-completed, .status-confirmed, .status-normal { background: rgb(237, 244, 255); color: rgb(36, 87, 166); }.status-pending, .status-waiting, .status-high { background: rgb(255, 244, 232); color: rgb(185, 89, 0); }.status-processing, .status-reviewed, .status-progress { background: rgb(238, 245, 255); color: rgb(22, 103, 177); }.rare { color: rgb(210, 45, 45); font-weight: 800; }.row-actions { display: flex; gap: 6px; white-space: nowrap; }.row-action { padding: 7px 9px; border: 1px solid rgb(190, 201, 216); background: rgb(255, 255, 255); color: rgb(35, 74, 124); }.row-action.danger { color: var(--danger); }.empty-state { padding: 50px 20px; text-align: center; color: var(--muted); }.modal { position: fixed; inset: 0px; z-index: 50; display: none; align-items: center; justify-content: center; padding: 20px; background: rgba(9, 20, 15, 0.58); }.modal.open { display: flex; }.modal-card { width: min(820px, 100%); max-height: 92vh; overflow: auto; border-radius: 13px; background: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.28) 0px 22px 70px; }.modal-header { display: flex; justify-content: space-between; gap: 20px; padding: 22px 24px; border-bottom: 1px solid var(--border); }.modal-header h2 { margin: 3px 0px 0px; }.close-button { border: 0px; background: transparent; font-size: 30px; color: rgb(82, 96, 112); cursor: pointer; }.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; padding: 24px; }.field { display: grid; gap: 7px; }.field.full { grid-column: 1 / -1; }.field label { font-size: 13px; font-weight: 800; color: rgb(52, 64, 84); }.field input, .field select, .field textarea { width: 100%; padding: 11px 12px; border: 1px solid rgb(186, 198, 214); border-radius: 7px; font: inherit; }.field textarea { min-height: 100px; resize: vertical; }.field input:disabled, .field textarea:disabled { background: rgb(245, 247, 250); color: rgb(71, 84, 103); }.modal-actions { display: flex; justify-content: flex-end; gap: 10px; padding: 18px 24px; border-top: 1px solid var(--border); }.report-viewer-card { width: min(1040px, 100%); max-height: 95vh; overflow: auto; border-radius: 13px; background: rgb(255, 255, 255); }.report-toolbar { display: flex; gap: 10px; justify-content: flex-end; padding: 15px 22px; border-bottom: 1px solid var(--border); }.report-meta { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; padding: 18px 22px; background: rgb(247, 249, 252); }.report-meta div { padding: 10px; border: 1px solid var(--border); border-radius: 7px; background: rgb(255, 255, 255); }.report-meta strong { display: block; font-size: 11px; text-transform: uppercase; color: var(--muted); margin-bottom: 5px; }.report-stage { padding: 22px; background: rgb(237, 241, 247); text-align: center; }.report-stage img { max-width: 100%; max-height: 72vh; object-fit: contain; background: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.12) 0px 4px 22px; }.toast { position: fixed; right: 24px; bottom: 24px; z-index: 80; padding: 13px 18px; border-radius: 8px; background: rgb(23, 63, 122); color: rgb(255, 255, 255); opacity: 0; transform: translateY(16px); pointer-events: none; transition: 0.2s; }.toast.show { opacity: 1; transform: translateY(0px); }@media (max-width: 1000px) {
