}.security-notice-modal { position: fixed; inset: 0px; z-index: 120; display: none; align-items: center; justify-content: center; padding: 22px; background: rgba(10, 18, 15, 0.62); backdrop-filter: blur(4px); }.security-notice-modal.open { display: flex; }.security-notice-card { position: relative; width: min(560px, 100%); overflow: hidden; border: 1px solid rgb(216, 225, 220); border-radius: 16px; background: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.34) 0px 30px 90px; }.security-notice-strip { height: 6px; background: rgb(36, 87, 166); }.security-notice-card.warning .security-notice-strip { background: rgb(217, 130, 24); }.security-notice-card.critical .security-notice-strip { background: rgb(201, 56, 56); }.security-notice-header { display: grid; grid-template-columns: 48px 1fr auto; gap: 14px; align-items: center; padding: 22px 24px 18px; border-bottom: 1px solid rgb(229, 235, 231); }.security-notice-icon { width: 48px; height: 48px; border-radius: 12px; display: grid; place-items: center; background: rgb(237, 244, 255); color: rgb(23, 63, 122); font-size: 23px; font-weight: 900; }.security-notice-card.warning .security-notice-icon { background: rgb(255, 244, 232); color: rgb(169, 83, 0); }.security-notice-card.critical .security-notice-icon { background: rgb(255, 240, 239); color: rgb(180, 35, 24); }.security-notice-kicker { text-transform: uppercase; letter-spacing: 0.11em; font-weight: 800; margin: 0px 0px 4px !important; font-size: 11px !important; color: rgb(102, 112, 133) !important; }.security-notice-header h2 { margin: 0px; font-size: 22px; color: rgb(23, 33, 27); }.security-notice-close { border: 0px; background: transparent; color: rgb(102, 112, 133); font-size: 28px; line-height: 1; cursor: pointer; }.security-notice-body { padding: 22px 24px; }.security-notice-body > p { margin: 0px; color: rgb(52, 64, 84); line-height: 1.65; white-space: pre-line; }.security-notice-meta { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 18